Ltac opt_blob OPT :=
  let jo := fresh "jo" in let OPTb := fresh "OPTb" in
  destruct (rw_cells_forget _ _ _ _ OPT) as [jo OPTb]; clear OPT; cbn [cells_size csize Nat.add OptItCells] in OPTb;
  try (match goal with SZ : cells_size _ = _ |- _ => rewrite SZ in OPTb; cbn [Nat.add] in OPTb end); rename OPTb into OPT.

(* [comment removed for export] *)
Ltac cl_shapeH S1L OPT :=
  lazymatch type of S1L with rw_cells _ _ ?spa [?c0; ?c1; ?c2; ?c3; ?c4; ?c5; ?c6; ?c7; ?c8; ?c9; ?c10; ?c11] =>
    let RST := fresh "RST" in let FF2 := fresh "FF2" in let MID := fresh "MID" in let EE := fresh "EE" in
    split_frameA S1L [c0; c1; c2; c3; c4; c5] [c6; c7; c8; c9; c10; c11] S1L RST; blob_at spa;
    split_frameA RST [c6; c7] [c8; c9; c10; c11] FF2 RST; split_frameA RST [c8; c9; c10] [c11] MID EE; blob_at (spa + 64);
    opt_blob OPT;
    lazymatch goal with BL : rw_cells _ _ spa [CB _ _], BM : rw_cells _ _ (spa + 64) [CB _ _] |- _ =>
      join_frameA BL FF2 spa; join_frameA BL BM spa; join_frameA BL EE spa; join_frameA BL OPT spa; rename BL into S1L end
  end.

