    opt_blob OPT;
    lazymatch goal with BL : rw_cells _ _ spa [CB _ _] |- _ =>
      join_frameA BL A1 spa; join_frameA T112 OPT (spa + 112); rename BL into S1L; rename T112 into S1H end
  end.

