Definition DOF_SHBCR : list byte :=
  map b8 ([0xf1; 0xf1; 0xf1; 0xf1; 0xf8; 0xf8; 0xf2; 0xf2; 0; 0; 0xf2; 0xf2; 0; 0; 0xf2; 0xf2; 0; 0; 0xf2; 0xf2] ++ DOF_SHTAIL).
Lemma shBC_B16 : firstn 2 (skipn 8 DOF_SHBC) = repeat (b8 0) 2.  Proof. reflexivity. Qed.
Lemma shBC_C16 : firstn 2 (skipn 12 DOF_SHBC) = repeat (b8 0) 2.  Proof. reflexivity. Qed.
Lemma shBCR_B16 : firstn 2 (skipn 8 DOF_SHBCR) = repeat (b8 0) 2.  Proof. reflexivity. Qed.
Lemma shBCR_C16 : firstn 2 (skipn 12 DOF_SHBCR) = repeat (b8 0) 2.  Proof. reflexivity. Qed.
Lemma shBCR_R16 : firstn 2 (skipn 16 DOF_SHBCR) = repeat (b8 0) 2.  Proof. reflexivity. Qed.

