Definition cl_lctx {HCEIL : HeapCeil} (H : asr) (LF : list fframe) (m m1 : mem) (sp : word) (spa : Z) (gsz : nat) (gj : list byte)
    (rav s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v : word)
    (P E vp : Z) (vbs : list byte) (c1 : pcore) (pad7 pad2 : list byte) (E0 : ecv) (g : bool) (lo shi ff fp : Z) (h0 h1 h2 h3 : word)
    (j0 : list byte) (tu : Z) (j64 j88 j112 : list byte) (optc : list cell) (hb : bool) (padC : list byte) (xv : Z) (jr shb : list byte) : Prop :=
  dof_ctx H LF m m1 sp spa gsz gj rav s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v P E vp vbs c1 pad7 pad2 (ErrCodeCells E0) g lo shi ff fp h0 h1 h2 h3 shb
  /\ rw_cells bsegs m1 spa [CB 8 j0; C8 (wz (ff + 128)); C8 (wz (Z.shiftr (P + 76) 3 + 2147450880)); C8 (wz (ff + 96)); C8 (wz tu); C8 (wz E);
                          C8 (wz ff); C8 (wz ff); CB 24 j64; CB 24 j88; CB 56 j112; C8 (wz E)]
  /\ rw_cells bsegs m1 (spa + 176) optc
  /\ rw_cells bsegs m1 (ff + 64) [C8 (wz vp); C8 (wz (Z.of_nat (length vbs)))]
  /\ rw_cells bsegs m1 (ff + 96) (OptU64Cells hb padC (wz xv))
  /\ rw_cells bsegs m1 (ff + 128) [CB 16 jr].

(* [comment removed for export] *)
Ltac cl_rebuild_ctx H m sp :=
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mx _) =>
  lazymatch goal with
  | GAP : rw_cells _ mx (?spa + 216) [CB ?gsz ?gj], SAV : rw_cells _ mx (bv_unsigned sp + -104) _,
    FH : rw_cells _ mx ?ff [C8 ?h0; C8 ?h1; C8 ?h2; C8 ?h3], FT : rw_cells _ mx (?ff + 504) [C8 _],
    SHU : rw_cells _ mx (Z.shiftr ?ff 3 + 2147450880) [CB 64 ?shb], FL : rw_cells _ mx ?fp [C1 (b8 1)],
    PC : rw_cells _ mx ?P (C8 (Z_to_bv 64 AVP_PARSER) :: _), SD : dof_side _ ?LF m mx ?lo ?shi ?ff ?fp ?P ?E ?vp _,
    EC : rw_cells _ mx ?E [C8 (Z_to_bv 64 (ec_val ?E0)); _; _], WIN : bytes_at _ mx ?vp ?vbs, HC : AHttpCat mx ?g, ST : stk _ mx ?lo ?spa,
    MU : munch _ m mx, WM : wmono _ m mx, MI : mem_inv _ mx, RA : bv_unsigned ?rav mod 2 = 0, SHFF : Z.shiftr ?ff 3 + 2147450880 = sh ?ff,
    S1L : rw_cells _ mx ?spa [CB 8 ?j0; _; _; _; C8 (Z_to_bv 64 ?tu); _; _; _; CB 24 ?j64; CB 24 ?j88; CB 56 ?j112; _],
    OPT : rw_cells _ mx (?spa + 176) ?optc, LST : rw_cells _ mx (?ff + 64) [C8 _; C8 _],
    COB : rw_cells _ mx (?ff + 96) [C1 (b8 ?hz); CB 7 ?padC; C8 (Z_to_bv 64 ?xv)], ROB : rw_cells _ mx (?ff + 128) [CB 16 ?jr] |- _ =>
    let hb := lazymatch hz with Z.b2z ?b => b | 1 => constr:(true) | 0 => constr:(false) end in
    lazymatch type of PC with rw_cells _ _ _ [_; C1 (b8 ?bh); CB 7 ?pad7; C8 (Z_to_bv 64 ?bl); C8 (Z_to_bv 64 ?ln); C8 (Z_to_bv 64 ?ln0); _; _;
                                         C8 (Z_to_bv 64 ?sk); C4 (Z_to_bv 64 ?hl); _; CB 2 ?pad2; C4 (Z_to_bv 64 ?st); C4 (Z_to_bv 64 ?f)] =>
    lazymatch type of SAV with rw_cells _ _ _ [C8 ?s11v; C8 ?s10v; C8 ?s9v; C8 ?s8v; C8 ?s7v; C8 ?s6v; C8 ?s5v; C8 ?s4v; C8 ?s3v; C8 ?s2v; C8 ?s1v; C8 ?s0v; C8 _] =>
      let L := fresh "LCTX" in
      assert (L : cl_lctx H LF m mx sp spa gsz gj rav s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v P E vp vbs
                      (mkPC bh bl ln ln0 sk hl st f) pad7 pad2 E0 g lo shi ff fp h0 h1 h2 h3 j0 tu j64 j88 j112 optc hb padC xv jr shb)
        by (unfold cl_lctx, dof_ctx, dof_sav, ParserCoreCells, ErrCodeCells, OptU64Cells; cbn [pc_blim_has pc_blim pc_len pc_len0 pc_skip pc_hlim pc_state pc_f]; unfold wz;
            repeat match goal with |- _ /\ _ => split end;
            first [exact GAP| exact SAV| exact FH| exact FT| exact SHU| exact FL| exact PC| exact EC| exact WIN| exact HC| exact ST
                  | unfold dof_WX, dof_W, AFS_FLAGS, AG_HTTP_CAT; cbn [app]; rewrite <- SHFF; exact MU| exact WM| exact MI| exact SD| exact RA
                  | exact S1L| exact OPT| exact LST| exact COB| exact ROB])
  end end end end.

