(* [comment removed for export] *)
Lemma shR_facts : forall (x y : byte) (shb : list byte), length shb = 64%nat ->
  firstn 2 (skipn 8 shb) = repeat (b8 0) 2 -> firstn 2 (skipn 12 shb) = repeat (b8 0) 2 ->
  length (take 16 shb ++ x :: y :: drop 2 (drop 16 shb)) = 64%nat
  /\ firstn 2 (skipn 8 (take 16 shb ++ x :: y :: drop 2 (drop 16 shb))) = repeat (b8 0) 2
